public class IdentifierRenamerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void finish() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    public static void main(String[] args) {
        check("letters are identifier parts", true, IdentifierRenamer.isIdentifierPart('x'));
        check("digits are identifier parts", true, IdentifierRenamer.isIdentifierPart('7'));
        check("dollar is an identifier part", true, IdentifierRenamer.isIdentifierPart('$'));
        check("a dot is not", false, IdentifierRenamer.isIdentifierPart('.'));
        check("occurrences skips longer names", 2,
                IdentifierRenamer.occurrences("count = count1 + count;", "count"));
        check("occurrences with no match", 0,
                IdentifierRenamer.occurrences("total = 1;", "count"));
        check("rename leaves longer names alone", "total = count1 + total;",
                IdentifierRenamer.rename("count = count1 + count;", "count", "total"));
        check("rename at the very start and end", "total + x + total",
                IdentifierRenamer.rename("count + x + count", "count", "total"));
        check("underscored name is not a match", "int myCount = total;",
                IdentifierRenamer.rename("int myCount = my_count;", "my_count", "total"));
        check("a field access is renamed", "this.total++;",
                IdentifierRenamer.rename("this.count++;", "count", "total"));
        check("empty oldName changes nothing", "count = 1;",
                IdentifierRenamer.rename("count = 1;", "", "total"));
        finish();
    }
}

