public class IdentifierRenamer {

    public static boolean isIdentifierPart(char c) {
        return Character.isLetterOrDigit(c) || c == '_' || c == '$';
    }

    private static boolean isWholeMatch(String source, String name, int start) {
        if (start > 0 && isIdentifierPart(source.charAt(start - 1))) {
            return false;
        }
        int after = start + name.length();
        return after >= source.length() || !isIdentifierPart(source.charAt(after));
    }

    public static int occurrences(String source, String name) {
        if (name.isEmpty()) {
            return 0;
        }
        int count = 0;
        int i = source.indexOf(name);
        while (i >= 0) {
            if (isWholeMatch(source, name, i)) {
                count++;
            }
            i = source.indexOf(name, i + 1);
        }
        return count;
    }

    public static String rename(String source, String oldName, String newName) {
        if (oldName.isEmpty()) {
            return source;
        }
        StringBuilder out = new StringBuilder();
        int i = 0;
        while (i < source.length()) {
            if (source.startsWith(oldName, i) && isWholeMatch(source, oldName, i)) {
                out.append(newName);
                i += oldName.length();
            } else {
                out.append(source.charAt(i));
                i++;
            }
        }
        return out.toString();
    }
}
